buildMap();
/* URL 参数引导（供自动化验证复现交互态）：?cmp=ABCD&wr=70&wc=20&wq=10 */
(function boot(){
  const q=new URLSearchParams(location.search);
  if(q.get("cmp")){
    const ids=[...q.get("cmp").toUpperCase()].filter(id=>SITES.some(s=>s.id===id));
    if(ids.length>=2){state.cmp=new Set(ids.slice(0,MAXCMP));}
  }
  [["wr","wRent","wRentV"],["wc","wCommute","wCommuteV"],["wq","wQuality","wQualityV"]].forEach(([k,e,v])=>{
    const n=parseInt(q.get(k),10); if(n>=0&&n<=100){document.getElementById(e).value=n;document.getElementById(v).textContent=n;}
  });
})();
renderTable();

